import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { HttpClient, HttpParams } from '@angular/common/http';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Injectable({
  providedIn: 'root'
})
export class TagService {

  constructor(private http: HttpClient, private tost: TostbarService) {

  }




  async createTag(mdl: any): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl}${environment.coreservice}/tag/tagBuilder`, mdl)
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value, '');
        return res;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return res;
      }
    } catch (err) {
      this.tost.openSnackBar(`Tag creation failed ${err}`, 'E');
      return { msg: -1, error: err, value: '' };
    }
  }

  async getTaskList(nCaseid: string): Promise<any> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl}${environment.coreservice}/tag/taglist`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

}
