import { ChangeDetectorRef, Component, EventEmitter, Input, input, Output, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';

import { ButtonComponent } from '../../button/button.component';
import { TagFormComponent } from '../tag-form/tag-form.component';
import { TagService } from '../../../services/tag/tag.service';
import { TagRes } from '../../../interfaces/tag.interface';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { NgSelectModule } from '@ng-select/ng-select';
import { SelectedTagsComponent } from '../selected-tags/selected-tags.component';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'choose-tag',
  standalone: true,
  imports: [MatSelectModule, FormsModule, IconComponent, CommonModule, ButtonComponent, NgSelectModule, TagFormComponent, SelectedTagsComponent],
  templateUrl: './choose-tag.component.html',
  styleUrl: './choose-tag.component.scss'
})
export class ChooseTagComponent {
  @Input() nCaseid: string;
  @Input() ismyfiles: boolean = true;
  @Input() selectedtaglist: TagRes[] = [];
  @Output() changeTag: EventEmitter<toolEvents> = new EventEmitter();
  selectedtag: any;
  taglist: TagRes[] = [];
  subtaglist: TagRes[] = [];
  @Input() nTagid: string = null;
  @Input() isedit: boolean = false;
  choosedtag: any;
  @Input() isSuccess: boolean = false;
  filteredTaglist: TagRes[] = []; // Added for search functionality

  // New properties for inline tag form
  showTagForm: boolean = false;
  editableTag: TagRes = null;

  selectedTag: any = null;

  constructor(private tagService: TagService,
    private cdr: ChangeDetectorRef, private tost: TostbarService
  ) { }


  async ngOnInit() {
    // Initialize filtered list
    this.filteredTaglist = [];
  }

  async ngOnChanges(changes: SimpleChanges) {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    await this.getTags();
    if (changes['isedit'] && changes['isedit'].currentValue == true) {
      this.addtag(this.nTagid);
    }
  }

  addtag(nTagid?) {

    if (nTagid) {
      this.choosedtag = this.taglist.find(e => e.nTagid == nTagid);
      if (!this.choosedtag) {
        this.subtaglist.forEach(e => {
          if (e.nTagid == nTagid) {
            let tag = this.taglist.find(a => a.nTagid == e.nParenttagid);
            tag.nParenttagid = e.nTagid;
            tag.cSubtag = e.cTag;
            this.choosedtag = tag;
          }
        });
      }
      this.editableTag = this.choosedtag;
    } else {
      this.editableTag = null;
    }

    this.showTagForm = true;
    this.cdr.detectChanges();
  }

  // New method to handle tag form closure
  onTagFormClosed(result: any) {
    this.showTagForm = false;
    this.editableTag = null;
    if (result) {
      this.getTags();
    }
    this.cdr.detectChanges();
  }

  // Method to close tag form without submitting
  closeTagForm() {
    this.showTagForm = false;
    this.editableTag = null;
    this.cdr.detectChanges();
  }





  // New method to handle mat-select change event
  onTagSelectionChange(event: any) {
    debugger;


    this.selectedTag = this.filteredTaglist.find(a => a.nTagid == event.value);

    this.choosedtag = event.value;
    this.nTagid = event.value?.nTagid || null;
    this.cdr.detectChanges();
  }

  // Search method to filter tags
  onSearchChange(searchTerm: string) {
    if (!searchTerm || searchTerm.trim() === '') {
      this.filteredTaglist = [...this.taglist];
    } else {
      const searchLower = searchTerm.toLowerCase().trim();
      this.filteredTaglist = this.taglist.filter(tag =>
        tag.cTag && tag.cTag.toLowerCase().includes(searchLower)
      );
    }

    // Reset selection if current selection is not in filtered results
    if (this.choosedtag && !this.filteredTaglist.find(tag => tag.nTagid === this.choosedtag.nTagid)) {
      this.choosedtag = null;
      this.nTagid = null;
    }
  }


  getTags(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.tagService.getTaskList(this.nCaseid).then((res: any) => {

        this.taglist = res[0];
        this.subtaglist = res[1];
        if (res[1] && res[1].length > 0) {
          for (let row of res[1]) {
            let ind = this.taglist.findIndex(e => e.nTagid == row.nParenttagid);
            if (ind > -1) {
              if (!this.taglist[ind].sublist) {
                this.taglist[ind].sublist = [];
              }
              this.taglist[ind].sublist.push(row);
            }
          }
        }
        
        this.filteredTaglist = [...this.taglist]; // Initialize filtered list
        this.filteredTaglist.sort((a, b) => a.cTag.localeCompare(b.cTag));

        // sort alphabtiocaly 

        if (this.choosedtag && this.choosedtag.nTagid) {
        this.taglist.sort((a, b) => a.cTag.localeCompare(b.cTag));
          this.choosedtag = this.taglist.find(a => a.nTagid == this.choosedtag.nTagid) ? this.taglist.find(a => a.nTagid == this.choosedtag.nTagid) : null;
        }
        this.cdr.detectChanges();
        resolve();
      }).catch(error => {
        reject(error);
      });
    });
  }

  Savetag() {
    if (!this.choosedtag) return;
    const ind = this.selectedtaglist.findIndex(a => a.nTagid == this.choosedtag);
    if (ind == -1) {
      this.selectedtaglist.unshift(this.selectedTag);
      // this.selectedContacts = [...this.selectedContacts]
      this.choosedtag = null;
      this.nTagid = null;
      this.selectedTag = null;
      this.cdr.detectChanges();
      this.changeTag.emit({ event: 'SUBMIT', data: {} });
    } else {
      this.tost.openSnackBar('Tag already added', 'E');
    }
  }



  selectTag() {
    this.choosedtag = this.taglist.find(a => a.nTagid == this.nTagid);
    this.cdr.detectChanges();
  }

  view() {
    this.changeTag.emit({ event: 'VIEW', data: {} });
  }

  back() {
    // Handle back navigation - you can customize this based on your needs
    this.changeTag.emit({ event: 'BACK', data: {} });
  }

  async changeSelectedTag(e: any) {
    this.changeTag.emit(e);
  }


}
