import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { pasteBundleReq, viewBundlesRes } from '../../../interfaces/myfile.interface';

@Component({
  selector: 'selected-custombundle',
  standalone: true,
  imports: [ButtonComponent, IconComponent],
  templateUrl: './selected-custombundle.component.html',
  styleUrl: './selected-custombundle.component.scss'
})
export class SelectedCustombundleComponent {
  @Input() nCaseid: string;
  @Input() nSectionid: string;
  @Input() jBDids: string[] = [];
  @Input() bundleList: viewBundlesRes[] = [];
  @Output() changeCustombundle: EventEmitter<string> = new EventEmitter();
  constructor(private mfs: MyfileService, private cdr: ChangeDetectorRef) { }


  ngOnInit(): void {

  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["bundleList"]) {
      this.cdr.detectChanges();
    }
  }


  async deleteBundle(x, ind) {
    var mdl: pasteBundleReq = { jFolders: JSON.stringify({}), jFiles: `{${this.jBDids.join(',')}}` };
    mdl.nSectionid = x.nSectionid;

    mdl["nBundleid"] = x.nBundleid ? x.nBundleid : null;
    var res: boolean = await this.mfs.unassignBundle(mdl)
    
    if (res) {
      this.bundleList.splice(ind, 1);
      this.cdr.detectChanges();
    }
  }

  viewFolder(x) {
    this.changeCustombundle.emit('OPEN_F_' + x.nBundleid);
  }

}
