import { Component, Input, Output, EventEmitter } from '@angular/core';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { ColorpickerComponent } from '../../colorpicker2/colorpicker/colorpicker.component';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { TagService } from '../../../services/tag/tag.service';
import { TagRes } from '../../../interfaces/tag.interface';

@Component({
  selector: 'tag-form',
  standalone: true,
  imports: [ButtonComponent, IconComponent, ColorpickerComponent, CommonModule, MatMenuModule,
    ReactiveFormsModule
  ],
  templateUrl: './tag-form.component.html',
  styleUrl: './tag-form.component.scss'
})
export class TagFormComponent {
  @Input() editable_list: TagRes;
  @Input() nCaseid: string;
  @Output() formClosed = new EventEmitter<any>();
  
  cClr: string = '#ff0000';
  tg_frm: FormGroup;
  colorslist: any = [
    { name: 'Red', cClr: '#ff0000' },
    { name: 'Green', cClr: '#00ff00' },
    { name: 'Blue', cClr: '#0000ff' },
  ]
  issubTag: boolean = false;
  
  constructor(private tagService: TagService) {

  }

  ngOnInit(): void {
    
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.tg_frm = new FormGroup({
      nCaseid: new FormControl(this.nCaseid),
      nTagid: new FormControl(0),
      cTag: new FormControl('', [Validators.required]),
      cSubtag: new FormControl(''),
      cDesc: new FormControl(''),
      nParenttagid: new FormControl(0),
      permission: new FormControl('N')
    });
    
    if (this.editable_list) {
      this.fillDetail();
    } else {
      this.tg_frm.patchValue({
        permission: 'N'
      })
    }
  }

  fillDetail() {
    this.tg_frm.patchValue({
      nTagid: this.editable_list.nTagid,
      cTag: this.editable_list.cTag,
      cSubtag: this.editable_list.cSubtag,
      nParenttagid: this.editable_list.nParenttagid,
      cDesc: this.editable_list.cDesc,
      permission: 'E'
    });
    if(this.editable_list.cSubtag){
      this.issubTag = true;
    }
    // if (this.editable_list.sublist && this.editable_list.sublist.length) {
    //   this.issubTag = true;
    //   this.tg_frm.patchValue({
    //     cSubtag: this.editable_list.sublist[0].cTag
    //   });
    // }
    this.cClr = this.editable_list.cClr;
  }

  close() {
    this.formClosed.emit(false);
  }

  async submit() {
    if (this.tg_frm.invalid) {
      return;
    }
    let mdl = this.tg_frm.value;
    mdl.cClr = this.cClr;
    mdl.nCaseid = this.nCaseid;
    mdl.cSubtag = mdl.cSubtag ? mdl.cSubtag : '';
    let res = await this.tagService.createTag(mdl);
    if (res && res.msg == 1) {
      this.formClosed.emit(true);
    }
  }

  async deleteTag() {
    let mdl = this.tg_frm.value;
    mdl.cClr = this.cClr;
    mdl.nCaseid = this.nCaseid;
    mdl.cSubtag = mdl.cSubtag ? mdl.cSubtag : '';
    mdl.permission = 'D';
    let res = await this.tagService.createTag(mdl);
    if (res && res.msg == 1) {
      this.formClosed.emit(true);
    }
  }


}
