import { CommonModule } from '@angular/common';
import { Component, Input, ChangeDetectorRef, EventEmitter, Output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatMenuModule } from '@angular/material/menu';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { MatTooltipModule } from '@angular/material/tooltip';
import { customviewListRes } from '../../../interfaces/properties.interface';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { BundlemanageService } from '../../../../adminpanel/services/bundle-manage/bundlemanage.service';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { InputComponent } from '../../input/input.component';
import { SourceCardComponent } from '../../source-card/source-card.component';
import { assignCustomBundleReq, bundleBuilder, bundleBuilderRes, viewBundlesRes } from '../../../interfaces/myfile.interface';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { EmptyComponent } from '../../empty/empty.component';

@Component({
  selector: 'choose-custombundle',
  standalone: true,
  imports: [CommonModule, FormsModule, MatRadioModule, MatSelectModule, MatMenuModule, MatTooltipModule, IconComponent, ButtonComponent, InputComponent, SourceCardComponent, EmptyComponent],
  providers: [BundlemanageService, MyfileService],
  templateUrl: './choose-custombundle.component.html',
  styleUrl: './choose-custombundle.component.scss'
})
export class ChooseCustombundleComponent {
  @Input() viewsection: boolean;
  @Input() ismyfiles: boolean;
  @Input() nCaseid: string;
  @Input() bundleList: viewBundlesRes[] = [];
  @Input() jBDids: number[] = [];
  custom_folderid: string;
  nSectionid: string;
  nBundleid: string;
  sub_list: any = [];
  maxrow: number = 6;
  alreadyexist: boolean = false;
  inprocess: boolean = false;
  isSuccess: boolean = false;
  @Input() viewlist: customviewListRes[] = [];
  showaddnewfolder: boolean = false; show_maincombo: boolean = false;
  @Output() changeCustombundle: EventEmitter<string> = new EventEmitter();
  constructor(public cf: CommonfunctionService, private bundleS: BundlemanageService, private myfileS: MyfileService,
    private cdr: ChangeDetectorRef, private tost: TostbarService,
  ) { }



  ngOnInit(): void {
    this.initdetail();
    this.bundleS.getUserSections(this.nCaseid).then(res => {
      this.nSectionid = res[1].find(a => a.cFoldertype == 'CB').nSectionid;
      if (this.nSectionid) {
        this.get_detail(this.nSectionid);
      }
    });
  }
  // "nBundleid","cBundlename","nParentBundleid","nUserid" 
  async get_detail(nSectionid) {
    this.sub_list = [{ lv: 1, "nBundleid": 0, list: [{ nBundleid: null, cBundlename: 'Private bundle', 'cIsfolder': true, nSectionid: nSectionid }] }];
    let res = await this.getBundleList(0, 1);
    this.sub_list[0]["list"] = this.sub_list[0]["list"].concat(res);
    this.cdr.detectChanges();
    //   this.check_foralreadyexists();

  }

  initdetail() {

    var ls: any = [];
    for (let y of this.viewlist) {
      try {
        y['from_rng'] = [];
        y['to_rng'] = [];
        y['filter_pg'] = '1';
        if (y.cPage && y.cPage != '' && y.cPage.includes('-')) {
          var pgcnt = parseInt(y.cPage.split('-')[1]) + 1;
        }
        y["from_rng"] = y["from_rng"] ? y["from_rng"] : [];
        y["to_rng"] = y["to_rng"] ? y["to_rng"] : [];
        for (var ar = 1; pgcnt > ar; ar++) {
          y['from_rng'].push(ar);
          y['to_rng'].push(ar);
        }
        y['to_rng'] = y.to_rng.reverse();
        y.from_val = y.from_rng.length ? y.from_rng[0] : 0;
        y.to_val = y.to_rng.length ? y.to_rng[0] : 0;
      } catch (error) { }
    }
  }

  async getBundleList(nBundleid, lv): Promise<any[]> {
    var mdl = { nSectionid: this.nSectionid, nBundleid: nBundleid, pageNumber: 1 }
    var res = await this.myfileS.bundleList(mdl);
    return res;
  }


  changePagelevel(x) {
    this.alreadyexist = false;
    this.updateEndRangeList(x);
    this.check_foralreadyexists()
  }

  check_foralreadyexists() {
    var viewlist: object[] = [];
    for (var i = 0; this.viewlist.length > i; i++) {
      var obj: any[] = [];
      obj.push(this.viewlist[i]["nBundledetailid"])
      obj.push(this.viewlist[i]["cPage"])
      if (parseInt(this.viewlist[i]["filter_pg"]) == 2) {
        obj[1] = this.viewlist[i]["from_val"] + '-' + this.viewlist[i]["to_val"];
      }
      viewlist.push(obj);
    }

    this.myfileS.checkAssignBundleExists(this.nSectionid, this.nBundleid, viewlist).then(res => {
      if (res && res.msg == 1) {
        this.alreadyexist = true;
        this.viewlist.map(e => { if (res.ids.includes(e.nBundledetailid)) { e['cInserted'] = 'Y' } else { e['cInserted'] = null } })
      } else {
        this.alreadyexist = false;
        this.viewlist.map(e => e['cInserted'] = null)
      }
      this.cdr.detectChanges();
    })
  }

  async add_folder(x, ind) {
    try {
      if (!x.nm || (x.nm).trim() == '') {
        this.nBundleid = null;
        this.custom_folderid = null;
        return
      }
      // this.custom_folderid = null;
      var bnLevel = this.sub_list.find(e => e.nBundleid == (this.nBundleid ? this.nBundleid : null))["lv"];
      if (x.lv > 1 && bnLevel == x.lv) {
        this.nBundleid = this.sub_list.find(e => e.lv == (x.lv - 1))["nBundleid"];
      }

      const mdl: bundleBuilder = {
        nBundleid: this.nBundleid ? this.nBundleid : null,
        nParentBundleid: x.lv == "1" ? "0" : this.nBundleid ? this.nBundleid : null,
        nCaseid: this.nCaseid,
        nSectionid: this.nSectionid || null,
        cBundlename: x.nm,
        permission: 'N'
      };
      if (x.list.find(e => e.cBundlename == x.nm)) {
        this.nBundleid = x.list.find(e => e.cBundlename == x.nm)["nBundleid"];
        this.sub_list[ind]["nBundleid"] = this.nBundleid;
        return;
      }
      let res: bundleBuilderRes = await this.myfileS.bundleBuilder(mdl);
      if (res && res["msg"] == 1) {

        if (!this.sub_list[ind]["list"]) {
          this.sub_list[ind]["list"] = [];
        }
        this.sub_list[ind]["list"].push({ cBundlename: x.nm, "nBundleid": res["nBundleid"], "nParentBundleid": this.nBundleid });
        this.sub_list[ind]["nBundleid"] = res["nBundleid"];
        this.nBundleid = String(res.nBundleid);
        // this.select(x, x.list[x.list.length - 1], ind);
        if (!this.sub_list.find(e => !e.nBundleid)) {
          this.add_axtra(this.sub_list[ind], 'S', ind);
        }
        x.cIsshow = false;
      } else {
        this.nBundleid = this.sub_list.find(e => e.nm == x.nm)["nBundleid"];
      }
      this.check_foralreadyexists();
      this.cdr.detectChanges();
    } catch (error) {

    }
  }

  async select(x, y, ind) {

    try {
      this.sub_list.splice((ind + 1), this.sub_list.length);
    } catch (error) {
    }
    x.nm = y.cBundlename;
    x.nBundleid = y.nBundleid;
    x.cIsshow = !x.cIsshow;
    this.nBundleid = y.nBundleid;
    this.inprocess = true;
    if (y.nBundleid) {
      let res = await this.getBundleList(this.nBundleid, 1);
      this.inprocess = false;
      // this.sub_list.push({ lv: (x.lv + 1), nm: '', "nBundleid": 0, list: res });
      if (res && res.length) {
        if (!y.cIsfolder) {
          this.custom_folderid = null;
          this.sub_list.push({ lv: (x.lv + 1), nm: '', "nBundleid": 0, list: res });
        }
      }
    } else {
      this.inprocess = false;
      this.custom_folderid = this.nSectionid;
    }
    this.check_foralreadyexists();
    this.cdr.detectChanges();
    // this.mfs.check_foralreadyexists();
  }

  opendrop_combo(row, flag, index) {
    if (flag == 'M') {
      this.showaddnewfolder = true;
      this.show_maincombo = true;
    } else {
      row.showaddnewfolder = true;
      row.cIsshow = true;
      let ind = this.sub_list.findIndex(a => !a.nBundleid);
      if (ind != -1 && ind != index && this.sub_list[ind].nm == '') {
        this.sub_list.splice(ind, 1);
      }
    }
  }

  add_axtra(x, flag, ind1) {
    if (x.nm == '' || !this.nBundleid || ((ind1 + 1) >= this.maxrow)) {
      return;
    }
    if ((x.lv + 1) >= this.maxrow) {
      return;
    }
    if (x.nBundleid == null) {
      this.add_folder(x, ind1);
      setTimeout(async () => {
        let res = await this.getBundleList(this.nBundleid, 1);
      }, 200);
    } else {
      this.sub_list.push({ lv: ((x.lv >= 0) ? (x.lv + 1) : 1), nm: '', nBundleid: null, list: [] });
    }
    this.cdr.detectChanges();
  }

  async assign_file() {
    this.inprocess = true;
    this.isSuccess = false;
    let cPage = '';
    // if (this.viewlist[i]["filter_pg"] == 2 && this.viewlist[i]["from_val"] > 0 && this.viewlist[i]["to_val"] > 0) {
    //   cPage = this.viewlist[i]["from_val"] + '-' + this.viewlist[i]["to_val"];
    // }
    //  && a["cPage"] == ((this.viewlist[i]["filter_pg"] && cPage != '') ? cPage : a["cPage"])
    // const ind = this.bundleList.findIndex(a => a.nBundleid == this.nBundleid);
    if (!this.alreadyexist) {
      try {
        if (!this.nBundleid && !this.custom_folderid) {
          this.inprocess = false;
          this.isSuccess = false;
          return;
        }
        var viewlist: object[] = [];
        for (var i = 0; this.viewlist.length > i; i++) {
          var obj: any[] = [];
          obj.push(this.viewlist[i]["nBundledetailid"])
          obj.push(this.viewlist[i]["cPage"])
          if (this.viewlist[i]["filter_pg"] == 2) {
            obj[1] = this.viewlist[i]["from_val"] + '-' + this.viewlist[i]["to_val"];
          }
          viewlist.push(obj);
        }

        if (!viewlist.length) {
          return;
        }

        var mdl: assignCustomBundleReq = { jFiles: JSON.stringify(viewlist) };
        mdl.nSectionid = this.nSectionid;
        mdl["nBundleid"] = this.nBundleid ? this.nBundleid : null;
        var res = await this.myfileS.assignCustomBundle(mdl);
        if (res) {
          this.isSuccess = true;
          this.inprocess = false;
          this.custom_folderid = null;
          this.nBundleid = null;
          this.showaddnewfolder = false;
          this.get_detail(this.nSectionid);
          this.changeCustombundle.emit('SUBMIT');
          // this.mfs.isCustomAssign = true;

          // this.mfs.new_files_ids = [].concat.apply([], []);
          // this.mfs.new_copy_bundles = [].concat.apply([], viewlist.map(e => e.nBundledetailid));

          // var ob1 = this.bundlelistall.find(a => a.cFoldertype == 'CB');
          // var nCustombundleid = ob1 ? ob1.nFolderid : 0;
          // this.mfs.past_detail = { nFolderid: nCustombundleid, jFiles: JSON.stringify(viewlist.map(e => e.nBundledetailid)), jTobundle: JSON.stringify([this.mfs.nBundleid ? this.mfs.nBundleid : null]), copy_mode: 'C' };

          // var interval_undo = setInterval(() => { this.mfs.isCustomAssign = false; clearInterval(interval_undo) }, 6000)
          // // this.get_temp_bundle(res[0]["nMaxbundledetailid"]);
          // this.get_detail();
          // this.inprocess = false;
          // this.mfs.checkIsuconttag();
        }
      } catch (error) {
        this.inprocess = false;
        this.isSuccess = false;
      }
    } else {
      this.inprocess = false;
      this.isSuccess = false;
      this.tost.openSnackBar('Bundle already added', 'E');
    }
  }

  view() {
    this.changeCustombundle.emit('VIEW');
  }

  selctfolder() {

  }


  private updateEndRangeList(y) {

    try {      
      debugger;
      y['to_rng'] = [];
      if (y.cPage && y.cPage != '' && y.cPage.includes('-')) {
        var pgcnt = parseInt(y.cPage.split('-')[1]) + 1;
      }      
      y["to_rng"] = y["to_rng"] ? y["to_rng"] : [];
      for (var ar = 1; pgcnt > ar; ar++) {
        if(y['from_val'] && ar < y['from_val']){
          continue;
        }        
        y['to_rng'].push(ar);
      }
      y['to_rng'] = y.to_rng.reverse();
      // y.from_val = y.from_rng.length ? y.from_rng[0] : 0;
      // y.to_val = y.to_rng.length ? y.to_rng[0] : 0;
    } catch (error) { }
    this.cdr.detectChanges();
  }


}
