import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { TagRes } from '../../../interfaces/tag.interface';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { MatDialog } from '@angular/material/dialog';
import { TagFormComponent } from '../tag-form/tag-form.component';
import { TagService } from '../../../services/tag/tag.service';

@Component({
  selector: 'selected-tags',
  standalone: true,
  imports: [ButtonComponent, IconComponent, CommonModule],
  templateUrl: './selected-tags.component.html',
  styleUrl: './selected-tags.component.scss'
})
export class SelectedTagsComponent {
  @Input() selectedtaglist: any = [];
  @Input() issubTag: boolean = false;
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();

  taglist: TagRes[] = [];
  subtaglist: TagRes[] = [];
  dialogRef: any;
  constructor(private crd: ChangeDetectorRef, private dialog: MatDialog, private tagService: TagService) { }


  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.

  }
  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    this.crd.detectChanges();
  }

  removeTag(x, ind) {
    this.selectedtaglist.splice(ind, 1);
    this.OnEvent.emit({ event: 'DELETE', data: { nTagid: x.nTagid } });
  }


  async edit(x?) {
    let nTagid = x.nTagid;
    await this.getTags();
    let choosedtag = this.taglist.find(e => e.nTagid == nTagid);
    
    if (nTagid) {
      if (!choosedtag) {
        this.subtaglist.forEach(e => {
          if (e.nTagid == nTagid) {
            let tag = this.taglist.find(a => a.nTagid == e.nParenttagid);
            tag.nParenttagid = e.nTagid;
            tag.cSubtag = e.cTag;
            choosedtag = tag;
          }
        });
      }
    }
    this.dialogRef = this.dialog.open(TagFormComponent, {
      width: '436px',
      height: 'calc(100% - 220px)',
      hasBackdrop: false,
      panelClass: 'noshadow',
      position: {
        top: `200px`,
        right: `24px`,
      }
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    if (nTagid) {
      this.dialogRef.componentInstance.editable_list = choosedtag;
    }
    this.dialogRef.afterClosed().subscribe(result => {
      this.dialogRef = null;
      if (result) {
        this.OnEvent.emit({ event: 'DELETE', data: { nTagid: x.nTagid } });
      }
    });
  }


  getTags(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.tagService.getTaskList(this.nCaseid).then((res: any) => {
        this.taglist = res[0];
        this.subtaglist = res[1];
        if (res[1] && res[1].length > 0) {
          for (let row of res[1]) {
            let ind = this.taglist.findIndex(e => e.nTagid == row.nParenttagid);
            if (ind > -1) {
              if (!this.taglist[ind].sublist) {
                this.taglist[ind].sublist = [];
              }
              this.taglist[ind].sublist.push(row);
            }
          }
        }
        resolve();
      }).catch(error => {
        reject(error);
      });
    });
  }


}
