import { CUSTOM_ELEMENTS_SCHEMA, ChangeDetectorRef, Component, EventEmitter, Input, Output, OnInit, OnDestroy } from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { MetadataComponent } from '../view/metadata/metadata.component';
import { ChooseContactComponent } from '../../contacts/choose-contact/choose-contact.component';
import { ChooseTaskComponent } from '../../tasks/choose-task/choose-task.component';
import { ChooseTagComponent } from '../../tags/choose-tag/choose-tag.component';
import { ChooseCustombundleComponent } from '../../costombundle/choose-custombundle/choose-custombundle.component';
import { SelectedCustombundleComponent } from '../../costombundle/selected-custombundle/selected-custombundle.component';
import { SelectedContactComponent } from '../../contacts/selected-contact/selected-contact.component';
import { selectedContactList, selectedTaskList } from '../../../interfaces/issue.interface';
import { SelectedTagsComponent } from '../../tags/selected-tags/selected-tags.component';
import { TagFormComponent } from '../../tags/tag-form/tag-form.component';
import { customviewListRes } from '../../../interfaces/properties.interface';
import { TAB_LIST, TabListItem, TAB_TYPE, PROPERTIES_EVENTS } from '../../../../shared/interfaces/properties-events.interface';
import { TranslateModule } from '@ngx-translate/core';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { assignContact, assignTag, assignTask, viewBundlesRes } from '../../../interfaces/myfile.interface';
import { SelectedTasksComponent } from '../../tasks/selected-tasks/selected-tasks.component';
import { ButtonComponent } from '../../button/button.component';
import { Filemetadata, TagRes } from '../../../interfaces/tag.interface';
import { TagService } from '../../../services/tag/tag.service';
import { EmptyComponent } from '../../empty/empty.component';
import { SourceCardComponent } from '../../source-card/source-card.component';
import { MatDialog } from '@angular/material/dialog';
import { AssignContactComponent } from '../../../../marking/components/fact/assign-contact/assign-contact.component';
import { AssignFactTaskComponent } from '../../../../marking/components/fact/assign-fact-task/assign-fact-task.component';
@Component({
  selector: 'app-properties',
  standalone: true,
  imports: [IconComponent, CommonModule, ButtonComponent, IconComponent,
    ChooseCustombundleComponent, ChooseContactComponent, ChooseTaskComponent, ChooseTagComponent, MetadataComponent
    , SelectedCustombundleComponent, SelectedContactComponent, SelectedTagsComponent, TagFormComponent,
    SelectedTasksComponent, EmptyComponent, SourceCardComponent, AssignContactComponent, AssignFactTaskComponent,
    TranslateModule],
  // RtFactAssigneeComponent
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
  templateUrl: './properties.component.html',
  styleUrl: './properties.component.scss'
})

export class PropertiesComponent implements OnInit, OnDestroy {
  public readonly TAB_TYPE = TAB_TYPE;
  @Input() viewsection: boolean;
  @Input() rightpanelwidth: number;
  @Input() nCaseid: string;
  @Input() nSectionid: string;
  @Input() viewlist: customviewListRes[] = [];
  @Input() ismyfiles: boolean = true;
  @Output() changeProperties: EventEmitter<any> = new EventEmitter();
  @Input() isTaskPermission: boolean = true;
  @Input() isContactPermission: boolean = true;
  selectedtab: any = null;
  slectedisempty: any = false;
  selectedtaglist: TagRes[] = [];

  tablist: TabListItem[] = [...TAB_LIST];
  active_form: boolean = false;
  jBDids: string[] = [];
  selectedContacts: selectedContactList[] = [];
  selectedTasks: selectedTaskList[] = [];
  bundleList: viewBundlesRes[] = [];
  editid: string;
  isedit: boolean = false;
  isSuccess: boolean = false;
  metadata: Filemetadata[];

  constructor(
    private readonly mfs: MyfileService,
    private readonly tagService: TagService,
    private readonly crd: ChangeDetectorRef,
    private readonly dialog: MatDialog
  ) {}

  ngOnInit(): void {
    this.jBDids = this.viewlist.map(x => x.nBundledetailid);
    this.viewFileMetadata();
    this.handleMenuView();
  }

  async selecttab(x) {

    this.isSuccess = false;
    this.isedit = false;
    this.editid = null;
    this.tablist.forEach(element => {
      element.isactive = false;
    });
    x.isactive = true;
    this.selectedtab = x;
    switch (x.type) {
      case TAB_TYPE.CUSTOM_BUNDLE:
        await this.getViewCBundleList();
        this.slectedisempty = !!this.bundleList;
        break;
      case TAB_TYPE.CONTACT:
        await this.getcontacts();
        this.slectedisempty = !!this.selectedContacts;
        break;
      case TAB_TYPE.TASK:
        await this.getTask();
        this.slectedisempty = !!this.selectedTasks;
        break;
      case TAB_TYPE.TAG:
        await this.getselectedTags();
        this.slectedisempty = !!this.selectedtaglist;
        break;
      default:
        this.slectedisempty = false;
    }
  }

  close() {
    this.changeProperties.emit({ event: PROPERTIES_EVENTS.CLOSE, data: {} });
  }

  back() {
    this.selectedtab = null;
  }

  async getViewCBundleList() {
    this.bundleList = await this.mfs.viewCustombundles(this.nCaseid, this.jBDids);
    this.crd.detectChanges();
  }

  async getcontacts() {
    this.selectedContacts = await this.mfs.viewContact(this.jBDids);
    this.crd.detectChanges();
  }


  async getTask() {
    this.selectedTasks = await this.mfs.viewTask(this.jBDids, 'FT');
    this.crd.detectChanges();
  }

  async getselectedTags() {
    this.selectedtaglist = await this.mfs.viewTag(this.jBDids);
    this.crd.detectChanges();
  }

  async changeTask(e) {
    if (e.event === PROPERTIES_EVENTS.SUBMIT) {
      if (this.selectedTasks.length > 0) {
        const nTaskid = this.selectedTasks[0].nTaskid;
        const mdl: assignTask = { nTaskid, jFiles: JSON.stringify(this.jBDids) };
        const res = await this.mfs.assignTask(mdl);
        if (res) {
          this.isSuccess = true;
        } else {
          await this.getTask();
        }
      }
      this.crd.detectChanges();
    } else if (e.event === PROPERTIES_EVENTS.VIEW) {
      this.viewsection = true;
    } else if (e.event?.includes(PROPERTIES_EVENTS.DELETE)) {
      const nTaskid = e.data?.nTaskid ?? 0;
      await this.unassingTask(nTaskid);
      this.changeProperties.emit('ASSIGN_VIEW');
    } else if (e.event?.includes(PROPERTIES_EVENTS.RELOAD)) {
      await this.getTask();
    } else if (e.event === PROPERTIES_EVENTS.CLOSE) {
      this.selectedtab = null;
      this.crd.detectChanges();
    }
  }

  async unassingTag(nTagid): Promise<boolean> {
    await this.mfs.unassigntag(nTagid, this.jBDids);
    this.crd.detectChanges();
    return true;
  }

  async unassingTask(nTaskid): Promise<boolean> {
    await this.mfs.unassigntask(nTaskid, this.jBDids);
    this.crd.detectChanges();
    return true;
  }

  async unassingContact(nContactid): Promise<boolean> {
    await this.mfs.unassignContact(nContactid, this.jBDids);
    this.crd.detectChanges();
    return true;
  }

  async changeTag(e) {
    switch (e.event) {
      case PROPERTIES_EVENTS.BACK:
        this.selectedtab = null;
        this.crd.detectChanges();
        break;
      case PROPERTIES_EVENTS.SUBMIT:
        if (this.selectedtaglist.length > 0) {
          const nTagid = this.selectedtaglist[0].nTagid;
          const mdl: assignTag = { nTagid, jFiles: JSON.stringify(this.jBDids) };
          const res = await this.mfs.assigntag(mdl);
          if (res) {
            this.isSuccess = true;
            this.changeProperties.emit(PROPERTIES_EVENTS.ASSIGN_VIEW);
          } else {
            await this.getselectedTags();
          }
        }
        this.crd.detectChanges();
        break;
      case PROPERTIES_EVENTS.VIEW:
        this.viewsection = true;
        this.isSuccess = false;
        this.crd.detectChanges();
        break;
      default:
        if (e.event?.includes('EDIT')) {
          this.editid = e.data?.nTagid ?? 0;
          this.isedit = true;
          this.viewsection = false;
        } else if (e.event?.includes(PROPERTIES_EVENTS.DELETE)) {
          const nTagid: number = e.data?.nTagid ?? 0;
          await this.unassingTag(nTagid);
          this.changeProperties.emit(PROPERTIES_EVENTS.ASSIGN_VIEW);
        } else if (e.event === PROPERTIES_EVENTS.RELOAD) {
          await this.getselectedTags();
        }
        break;
    }
  }

  async changeCustombundle(event) {
    if (event == PROPERTIES_EVENTS.SUBMIT) {
      this.getViewCBundleList();
      this.changeProperties.emit(PROPERTIES_EVENTS.ASSIGN_VIEW);
      this.isSuccess = true;
    } else if (event == PROPERTIES_EVENTS.VIEW) {
      this.isSuccess = false;
      this.viewsection = true;
    } else {
      this.changeProperties.emit(event);
    }
  }

  async changeContact(e) {
    if (e.event === PROPERTIES_EVENTS.SUBMIT) {
      if (this.selectedContacts.length > 0) {
        const nContactid = this.selectedContacts[0].nContactid;
        const mdl: assignContact = { nContactid, jFiles: JSON.stringify(this.jBDids) };
        const res = await this.mfs.assignContact(mdl);
        if (res) {
          this.isSuccess = true;
          this.changeProperties.emit(PROPERTIES_EVENTS.ASSIGN_VIEW);
        } else {
          await this.getcontacts();
        }
      }
      this.crd.detectChanges();
    } else if (e.event === PROPERTIES_EVENTS.RELOAD) {
      await this.getcontacts();
      this.crd.detectChanges();
    } else if (e.event === PROPERTIES_EVENTS.VIEW) {
      this.viewsection = true;
      this.isSuccess = false;
      this.crd.detectChanges();
    } else if (e.event?.includes(PROPERTIES_EVENTS.DELETE)) {
      const nContactid: number = e.data?.nContactid ?? 0;
      await this.unassingContact(nContactid);
      this.changeProperties.emit(PROPERTIES_EVENTS.ASSIGN_VIEW);
    } else if (e.event === PROPERTIES_EVENTS.CLOSE) {
      this.selectedtab = null;
      this.crd.detectChanges();
    }
  }
  ngOnDestroy(): void {
    this.dialog.closeAll();
  }

  onEventChange(event) {
    if (event.event == PROPERTIES_EVENTS.BACK) {
      this.selectedtab = null;
    }
  }

  async viewFileMetadata(): Promise<void> {
    const res = await this.mfs.viewFileMetadata(JSON.stringify(this.jBDids))
    this.metadata = res;
    this.crd.detectChanges();

  }

  handleMenuView() {
    for (const item of this.tablist) {
      if (item.type == TAB_TYPE.TASK) {
        item.hidden = !this.isTaskPermission;
      }
      if (item.type == TAB_TYPE.CONTACT) {
        item.hidden = !this.isContactPermission;
      }
    }
  }

  activeFormChange(event) {
    if (!event) {
      this.changeTask({ event: PROPERTIES_EVENTS.CLOSE, data: {} });
    }
    if (event == 'T') {
      this.changeTask({ event: PROPERTIES_EVENTS.SUBMIT, data: {} });
    }
  }
}
